primitives.latex:
S_{spread} = \begin{cases} WIN & \text{if } Margin_i - Line_i > 0 \
LOSS & \text{if } Margin_i - Line_i < 0 \
PUSH & \text{if } Margin_i - Line_i = 0 \end{cases}

S_{ml} = \begin{cases} WIN & \text{if } Winner = BettedTeam \
LOSS & \text{if } Winner \neq BettedTeam \
PUSH & \text{if } Draw \in Soccer \end{cases}

S_{total} = \begin{cases} OVER & \text{if } Total > Line \
UNDER & \text{if } Total < Line \
PUSH & \text{if } Total = Line \end{cases}
